def fetch_stock_institutional_flow(stock_id: str) -> Dict[str, Any]:
    try:
        end = now_tw().date()
        start = end - timedelta(days=45)
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {
            "dataset": "TaiwanStockInstitutionalInvestorsBuySell",
            "data_id": stock_id,
            "start_date": start.strftime("%Y-%m-%d"),
            "end_date": end.strftime("%Y-%m-%d"),
        }
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT)
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            return {"inst_5d": None, "inst_20d": None, "source": "FinMind 無資料"}
        df = pd.DataFrame(data)
        if "date" not in df.columns or "buy" not in df.columns or "sell" not in df.columns:
            return {"inst_5d": None, "inst_20d": None, "source": "欄位不完整"}
        df["date"] = pd.to_datetime(df["date"], errors="coerce")
        df["net"] = df["buy"].apply(to_float).fillna(0) - df["sell"].apply(to_float).fillna(0)
        df = df.dropna(subset=["date"]).sort_values("date")
        dates = sorted(df["date"].dropna().unique())
        d5 = dates[-5:]
        d20 = dates[-20:]
        return {
            "inst_5d": float(df[df["date"].isin(d5)]["net"].sum()),
            "inst_20d": float(df[df["date"].isin(d20)]["net"].sum()),
            "source": "FinMind",
        }
    except Exception as e:
        return {"inst_5d": None, "inst_20d": None, "source": f"失敗：{e}"}


def fetch_stock_month_revenue(stock_id: str) -> Dict[str, Any]:
    try:
        end = now_tw().date()
        start = end - timedelta(days=500)
        url = "https://api.finmindtrade.com/api/v4/data"
        params = {
            "dataset": "TaiwanStockMonthRevenue",
            "data_id": stock_id,
            "start_date": start.strftime("%Y-%m-%d"),
            "end_date": end.strftime("%Y-%m-%d"),
        }
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT)
        js = r.json()
        data = js.get("data", []) if isinstance(js, dict) else []
        if not data:
            return {"revenue_yoy": None, "source": "FinMind 無資料"}
        df = pd.DataFrame(data)
        if "date" not in df.columns or "revenue" not in df.columns:
            return {"revenue_yoy": None, "source": "欄位不完整"}
        df["date"] = pd.to_datetime(df["date"], errors="coerce")
        df["revenue"] = df["revenue"].apply(to_float)
        df = df.dropna(subset=["date", "revenue"]).sort_values("date")
        if df.empty:
            return {"revenue_yoy": None, "source": "有效資料空白"}
        latest = df.iloc[-1]
        for c in ["revenue_year_growth_rate", "YoY", "yoy"]:
            if c in df.columns:
                yoy = to_float(latest.get(c))
                if yoy is not None:
                    return {"revenue_yoy": yoy, "source": "FinMind"}
        latest_date = latest["date"]
        prev = df[(df["date"].dt.year == latest_date.year - 1) & (df["date"].dt.month == latest_date.month)]
        if prev.empty:
            return {"revenue_yoy": None, "source": "缺去年同期"}
        yoy = pct_change(latest["revenue"], prev.iloc[-1]["revenue"])
        return {"revenue_yoy": yoy, "source": "FinMind"}
    except Exception as e:
        return {"revenue_yoy": None, "source": f"失敗：{e}"}


def stock_position_label(tech: Optional[Dict[str, Any]]) -> str:
    if not tech:
        return "資料不足"
    above20 = bool(tech.get("above_ma20"))
    above60 = bool(tech.get("above_ma60"))
    if above20 and above60:
        return "站上MA20/MA60"
    if above20 and not above60:
        return "站上MA20，仍在MA60下"
    if not above20 and above60:
        return "跌破MA20，MA60仍守住"
    return "跌破MA20/MA60"


def classify_stock_for_radar(
    tech: Optional[Dict[str, Any]],
    flow: Dict[str, Any],
    rev: Dict[str, Any],
    radar_mode: str = "inflow",
    sector_flow_status: str = "",
) -> Tuple[str, str, str, str]:
    """依掃描目的分類：資金流入佈局 / 資金退潮風險。"""
    inst5 = to_float(flow.get("inst_5d"))
    inst20 = to_float(flow.get("inst_20d"))
    yoy = to_float(rev.get("revenue_yoy"))
    chg5 = to_float(tech.get("chg_5d")) if tech else None
    chg20 = to_float(tech.get("chg_20d")) if tech else None
    vol_ratio = to_float(tech.get("vol_ratio")) if tech else None
    above_ma20 = bool(tech.get("above_ma20")) if tech else False
    above_ma60 = bool(tech.get("above_ma60")) if tech else False

    inst5_buy = inst5 is not None and inst5 > 0
    inst20_buy = inst20 is not None and inst20 > 0
    inst5_sell = inst5 is not None and inst5 < 0
    inst20_sell = inst20 is not None and inst20 < 0
    yoy_good = yoy is not None and yoy > 0
    yoy_bad = yoy is not None and yoy <= 0
    hot = (chg5 is not None and chg5 >= 8) or (chg20 is not None and chg20 >= 20) or (vol_ratio is not None and vol_ratio >= 2.2)
    weak_trend = (not above_ma20) and (chg5 is not None and chg5 < 0)
    deep_weak = (not above_ma20) and (not above_ma60) and (chg20 is not None and chg20 < -5)
    sector_is_inflow = sector_flow_status in ["明面主流", "偷偷流入", "低基期轉強", "回檔轉強", "主流鈍化"]
    sector_is_outflow = sector_flow_status in ["退潮轉弱", "主流鈍化"]

    if radar_mode == "outflow":
        if inst5_sell and inst20_sell and not above_ma20 and (sector_flow_status == "退潮轉弱" or deep_weak):
            return "明確退潮，先避開", "法人短線與波段同步賣，且技術跌破短均；不要接刀", "避開 / 不追", "高"
        if chg20 is not None and chg20 >= 8 and ((chg5 is not None and chg5 <= 1) or not above_ma20) and (inst5_sell or sector_flow_status == "主流鈍化"):
            return "高檔鈍化，不追高", "前波已有漲幅，追價力道降溫；題材未必壞，但現在不適合追", "續抱觀察 / 等回檔", "中"
        if yoy_good and (inst5_sell or weak_trend) and not (inst20_sell and deep_weak):
            return "基本面沒壞，但資金短退", "營收仍有支撐，但短線資金退場；等止跌再看", "等止跌 / 觀察", "中"
        if yoy_good and not inst20_sell and (not above_ma20 or (chg5 is not None and chg5 < 0)) and (vol_ratio is None or vol_ratio < 1.8):
            return "疑似洗盤，觀察支撐", "法人沒有明顯大退，量能未失控；可能只是健康回檔", "觀察支撐", "低～中"
        if yoy_bad and deep_weak and (chg5 is not None and chg5 > 0):
            return "反彈逃命股", "趨勢與基本面都弱，短線反彈不代表轉強", "反彈不追", "高"
        if sector_is_outflow or inst5_sell or not above_ma20:
            return "退潮觀察", "已有資金轉弱訊號，但還需確認是否擴大", "降低追高慾望", "中"
        return "暫無明確退潮", "目前沒有明顯退潮訊號，列入觀察即可", "觀察", "低"

    # 個股低基期：不能只是「基本面轉強」，必須真的還在低位階。
    low_base_stock = (
        sector_flow_status == "低基期轉強"
        and chg20 is not None
        and chg20 <= 5
        and (chg5 is None or chg5 <= 5)
        and not hot
        and (not above_ma60 or not above_ma20)
        and yoy_good
        and not inst20_buy
    )

    # 回檔轉強：原本中期偏強，短線整理後重新轉強。
    pullback_stock = (
        sector_flow_status == "回檔轉強"
        and above_ma20
        and chg20 is not None
        and chg20 >= 3
        and (chg5 is None or chg5 <= 4)
        and not hot
    )

    # 先排除過熱，避免「已經噴出」被丟進佈局分類。
    if hot and sector_is_inflow:
        return "位置過熱，不追", "方向可能沒錯，但短線乖離偏高，等回檔比較安全", "等回檔", "中"
    if hot and (not yoy_good or not inst20_buy):
        return "題材先跑，基本面待驗證", "股價或量能先噴，但基本面/法人還沒完全跟上", "不重倉追", "中～高"

    if inst5_buy and inst20_buy and yoy_good and above_ma20:
        return "優先佈局觀察", "法人有卡位，基本面有撐，位置尚可", "可觀察 / 等回檔", "低～中"
    if pullback_stock and (yoy_good or inst5_buy):
        return "回檔轉強觀察", "族群屬回檔轉強，個股仍站上20日線，短線整理後再轉強；看支撐是否守住", "支撐不破可觀察", "中"
    if low_base_stock:
        return "低基期轉強觀察", "基本面有改善，但股價仍在低位階或剛翻上短均；法人尚未全面進場", "追蹤 / 等法人確認", "中"

    # 基本面轉強，法人剛卡位：
    # 不是「法人未跟上」，而是短線法人已開始買，但波段買盤尚未全面確認。
    if yoy_good and above_ma20 and inst5_buy and (inst20 is None or inst20 <= 0):
        return "基本面轉強，法人剛卡位", "營收有改善，法人短線剛開始卡位，但20日法人尚未全面轉強；觀察是否延續買超", "追蹤 / 等法人延續", "中"

    if inst5_buy and (inst20 is None or inst20 <= 0) and above_ma20:
        return "偷偷回補觀察", "法人短線剛回補，但基本面尚未確認或資料不足；適合先放觀察名單", "先觀察 / 不急追", "中"

    if yoy_bad and (chg5 is not None and chg5 > 3):
        return "題材先跑，基本面待驗證", "營收沒跟上，股價先跑，先不要追", "不追 / 等驗證", "中～高"
    return "佈局觀察中", "有資金或族群跡象，但條件還不夠完整", "觀察", "中"


def scan_sector_stock_radar(
    selected_sectors: List[str],
    max_stocks_each: int = 4,
    extra_pool: Optional[Dict[str, Any]] = None,
    radar_mode: str = "inflow",
    sector_status_lookup: Optional[Dict[str, str]] = None,
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    mode_label = RADAR_MODE_LABELS.get(radar_mode, "資金流入佈局")
    try:
        for sector in selected_sectors:
            sector_flow_status = (sector_status_lookup or {}).get(sector, "")
            for stock_id, stock_name in get_effective_sector_pool(sector, extra_pool)[:max_stocks_each]:
                tech = fetch_stock_price_tech(stock_id, period="6mo")
                flow = fetch_stock_institutional_flow(stock_id)
                rev = fetch_stock_month_revenue(stock_id)
                status, note, action, risk = classify_stock_for_radar(tech, flow, rev, radar_mode=radar_mode, sector_flow_status=sector_flow_status)
                rows.append(
                    {
                        "掃描模式": mode_label,
                        "族群": sector,
                        "族群資金狀態": sector_flow_status or "—",
                        "股票": f"{stock_name} {stock_id}",
                        "狀態": status,
                        "風險等級": risk,
                        "法人5日": flow.get("inst_5d"),
                        "法人20日": flow.get("inst_20d"),
                        "月營收YoY": rev.get("revenue_yoy"),
                        "5日漲跌": tech.get("chg_5d") if tech else None,
                        "20日漲跌": tech.get("chg_20d") if tech else None,
                        "量比": tech.get("vol_ratio") if tech else None,
                        "位置": stock_position_label(tech),
                        "操作": action,
                        "操作提醒": note,
                    }
                )
        if not rows:
            return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "mode": radar_mode, "mode_label": mode_label, "rows": []}, status_item("fail", False, "沒有掃到有效資料")
        return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "mode": radar_mode, "mode_label": mode_label, "rows": rows}, status_item("ok", True, f"{mode_label}完成掃描 {len(rows)} 檔")
    except Exception as e:
        return {"updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"), "mode": radar_mode, "mode_label": mode_label, "rows": rows}, status_item("partial", bool(rows), f"部分完成：{e}")



def _market_quote_after_close(realtime_quote: Optional[Dict[str, Any]]) -> bool:
    """判斷 TWSE MIS 報價是否可視為「已完成日K」補值。

    修正版重點：
    - 當天 13:30 後：可以補今天收盤。
    - 隔天早上：如果 MIS 報價日期已經是昨天或更早，代表那是已完成交易日，也可以補。
    - 盤中：如果 MIS 日期等於今天且未到收盤，不能納入計算，只能畫盤中K。
    """
    if not realtime_quote:
        return False

    try:
        now = now_tw()
        qdate = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
        if not pd.isna(qdate):
            q_norm = qdate.normalize()
            today_norm = pd.Timestamp(now.date())
            # 隔天或非當日盤中看到的 MIS 報價，視為上一個完成交易日，可以補進日K。
            if q_norm < today_norm:
                return True
    except Exception:
        pass

    try:
        qtime = str(realtime_quote.get("time") or "").strip()
        if qtime:
            parts = qtime.split(":")
            if len(parts) >= 2:
                hh = int(parts[0])
                mm = int(parts[1])
                if (hh, mm) >= (13, 30):
                    return True
    except Exception:
        pass

    try:
        now = now_tw()
        return (now.hour, now.minute) >= (13, 35)
    except Exception:
        return False


def _is_completed_market_date(dt: Any) -> bool:
    """判斷某日期是否可視為已完成日K。

    原則：
    - 早於今天：完成日K。
    - 今天：必須 13:35 後才算完成日K。
    - 今天盤中：不可併入正式日K，只能當盤中K顯示。
    """
    d = pd.to_datetime(dt, errors="coerce")
    if pd.isna(d):
        return False
    try:
        now = now_tw()
        d_norm = d.normalize()
        today_norm = pd.Timestamp(now.date())
        if d_norm < today_norm:
            return True
        if d_norm > today_norm:
            return False
        return (now.hour, now.minute) >= (13, 35)
    except Exception:
        return False


def _remove_unfinished_today_kline(df: pd.DataFrame) -> Tuple[pd.DataFrame, bool, str]:
    """移除 Yahoo/TWSE 可能塞進來的今日盤中日K。

    這是為了讓大盤K線行為跟個股分析器一致：
    - 已完成日K保留
    - 盤中K只在圖上另外新增
    - 盤中K不得覆蓋最後一根已完成日K
    """
    if df is None or df.empty or "date" not in df.columns:
        return df, False, "無資料"
    work = df.copy().sort_values("date").reset_index(drop=True)
    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")
    if pd.isna(last_date):
        return work, False, "最後日期無效"
    if not _is_completed_market_date(last_date):
        work = work.iloc[:-1].copy().reset_index(drop=True)
        finalized, err = _finalize_market_kline_df(work)
        if finalized is None:
            return df, False, f"移除盤中日K後整理失敗：{err}"
        return finalized, True, f"已移除未收盤日K {last_date.strftime('%Y-%m-%d')}，改由盤中K顯示"
    return work, False, "最後一根已完成"


def merge_market_realtime_quote_for_update(
    df: pd.DataFrame,
    realtime_quote: Optional[Dict[str, Any]],
) -> Tuple[pd.DataFrame, bool, str]:
    """大盤更新後補 TWSE MIS 最新報價。

    用途：
    - Yahoo Chart 日K常常盤後延遲，導致按「更新大盤」仍停在舊收盤。
    - 若已過收盤時間，MIS 有今日加權指數報價，則把它補成最新一根K。
    - 補值後重新計算 MA/VolMA，讓總覽、K線與裁決同步更新。

    注意：
    - 只有收盤後才補進計算。
    - 盤中仍維持原本規則：即時K只顯示，不納入計算。
    """
    if df is None or df.empty or not realtime_quote:
        return df, False, "無即時報價可補"

    q_price = to_float(realtime_quote.get("price"))
    q_date = pd.to_datetime(realtime_quote.get("date"), errors="coerce")
    if q_price is None or pd.isna(q_date):
        return df, False, "即時報價價格或日期無效"

    work = df.copy().sort_values("date").reset_index(drop=True)
    last_date = pd.to_datetime(work["date"].iloc[-1], errors="coerce")
    q_norm = q_date.normalize()

    # 是否可把 MIS 報價併入日K：
    # 1) 收盤後可併入；
    # 2) 隔天早上若 MIS 日期比 Yahoo 日K 新，也要併入，避免 Yahoo 日K延遲造成圖停在舊日期。
    can_merge_quote = _market_quote_after_close(realtime_quote)
    try:
        now_norm = pd.Timestamp(now_tw().date())
        if not pd.isna(last_date) and q_norm > last_date.normalize() and q_norm < now_norm:
            can_merge_quote = True
    except Exception:
        pass

    if not can_merge_quote:
        return df, False, "尚未收盤，盤中報價不納入大盤計算"

    q_open = to_float(realtime_quote.get("open")) or q_price
    q_high = to_float(realtime_quote.get("high")) or max(q_open, q_price)
    q_low = to_float(realtime_quote.get("low")) or min(q_open, q_price)
    q_volume = to_float(realtime_quote.get("volume")) or 0

    new_row = {
        "date": q_norm,
        "open": q_open,
        "max": max(q_high, q_open, q_price),
        "min": min(q_low, q_open, q_price),
        "close": q_price,
        "volume": q_volume,
    }

    merged = False
    if pd.isna(last_date) or q_norm > last_date.normalize():
        # Yahoo 日K還沒更新到今天：append 今日收盤
        work = pd.concat([work, pd.DataFrame([new_row])], ignore_index=True)
        merged = True
        note = f"已用 TWSE MIS 補上 {q_norm.strftime('%Y-%m-%d')} 收盤"
    elif q_norm == last_date.normalize():
        # 同一天但 Yahoo 值可能延遲/不同：用 MIS 覆蓋最新一根
        for k, v in new_row.items():
            if k in work.columns:
                work.loc[work.index[-1], k] = v
        merged = True
        note = f"已用 TWSE MIS 覆蓋 {q_norm.strftime('%Y-%m-%d')} 收盤"
    else:
        return work, False, "TWSE MIS 日期沒有比日K新"

    # 補值後重新計算均線與量均線，讓總覽與K線同步更新。
    for col in ["MA5", "MA10", "MA20", "MA60", "VolMA5", "VolMA20"]:
        if col in work.columns:
            work = work.drop(columns=[col])

    finalized, err = _finalize_market_kline_df(work)
    if finalized is None:
        return df, False, f"補值後整理失敗：{err}"

    return finalized, merged, note



# =========================================================
# 盤後資金結構 / 上漲來源
# =========================================================
def _parse_twse_money_value(v: Any) -> Optional[float]:
    """TWSE 金額欄位轉 float，保留元為單位。"""
    if v is None:
        return None
    try:
        s = str(v).replace(",", "").replace("+", "").strip()
        if s in ["", "-", "--", "nan", "None", "null"]:
            return None
        return float(s)
    except Exception:
        return None


def _twse_api_json(url: str, params: Dict[str, Any]) -> Tuple[Optional[Any], str]:
    try:
        r = requests.get(url, params=params, timeout=REQUEST_TIMEOUT, headers={"User-Agent": "Mozilla/5.0"})
        if r.status_code != 200:
            return None, f"HTTP {r.status_code}"
        js = r.json()
        return js, ""
    except Exception as e:
        return None, str(e)


def fetch_twse_institutional_amount(date: Optional[datetime] = None, lookback_days: int = 7) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """抓 TWSE 三大法人買賣超金額。

    僅抓上市 TWSE，因為加權指數主體是上市市場。
    單位換算成億元。若今日盤後資料尚未更新，往前找最近一個有資料的交易日。
    """
    base_d = date or now_tw()
    url = "https://www.twse.com.tw/rwd/zh/fund/BFI82U"
    last_err = ""

    for offset in range(0, max(1, int(lookback_days))):
        d = base_d - timedelta(days=offset)
        ymd = d.strftime("%Y%m%d")
        js, err = _twse_api_json(url, {"date": ymd, "response": "json"})
        if js is None:
            last_err = f"{ymd} {err}"
            continue

        data = js.get("data") or []
        if not data:
            last_err = f"{ymd} 無資料"
            continue

        result = {
            "date": ymd,
            "source": "TWSE BFI82U",
            "rows": [],
            "foreign": None,
            "investment_trust": None,
            "dealer": None,
            "total_inst": None,
            "other_estimate": None,
        }

        total_diff = 0.0
        has_any = False

        def classify_name(name: str) -> str:
            n = str(name)
            if "外資" in n or "陸資" in n:
                return "foreign"
            if "投信" in n:
                return "investment_trust"
            if "自營商" in n:
                return "dealer"
            return "other"

        for row in data:
            if not isinstance(row, list) or len(row) < 4:
                continue
            name = str(row[0])
            buy = _parse_twse_money_value(row[1])
            sell = _parse_twse_money_value(row[2])
            diff = _parse_twse_money_value(row[3])
            if diff is None and buy is not None and sell is not None:
                diff = buy - sell
            if diff is None:
                continue

            diff_100m = diff / 100_000_000
            key = classify_name(name)
            if key in ["foreign", "investment_trust", "dealer"]:
                if result.get(key) is None:
                    result[key] = 0.0
                result[key] += diff_100m
                total_diff += diff_100m
                has_any = True

            result["rows"].append({
                "名稱": name,
                "買進(億)": None if buy is None else round(buy / 100_000_000, 2),
                "賣出(億)": None if sell is None else round(sell / 100_000_000, 2),
                "買賣超(億)": round(diff_100m, 2),
            })

        if not has_any:
            last_err = f"{ymd} 格式異常"
            continue

        result["total_inst"] = total_diff
        # 其他資金推估：不是散戶，也不是主力；只是三大法人以外資金的相對方向估計。
        result["other_estimate"] = -total_diff
        status_note = f"TWSE 三大法人成功更新：{ymd}"
        if offset > 0:
            status_note += "（今日資料未出，採最近交易日）"
        return result, status_item("ok", True, status_note)

    return {}, status_item("partial", False, f"TWSE 三大法人資料尚未更新或抓取失敗：{last_err}")


def compute_market_rise_sources(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    """判斷今日大盤上漲來源。

    這不是精準指數貢獻分解，而是用目前 App 已有資料做「來源判讀」：
    - 大盤漲跌
    - 資金流向分類
    - 三大法人買賣超
    - 外部環境分數
    """
    market = snapshot.get("market") or {}
    flow = snapshot.get("flow") or {}
    inst = snapshot.get("institutional") or {}
    external = snapshot.get("external") or {}

    last = market.get("last") or {}
    change_pct = to_float(last.get("change_pct"))
    close = to_float(last.get("close"))

    rows = flow.get("rows") or []
    status_counts: Dict[str, int] = {}
    for r in rows:
        s = r.get("狀態") or "觀察中"
        status_counts[s] = status_counts.get(s, 0) + 1

    foreign = to_float(inst.get("foreign"))
    trust = to_float(inst.get("investment_trust"))
    dealer = to_float(inst.get("dealer"))

    external_score = None
    try:
        external_score = to_float((external.get("summary") or {}).get("score"))
    except Exception:
        external_score = None

    clues = []
    if change_pct is not None:
        if change_pct >= 2:
            clues.append("指數大漲，先判斷是否由權值股或外資回補推動")
        elif change_pct >= 0.8:
            clues.append("指數明顯上漲，觀察族群是否同步擴散")
        elif change_pct >= 0:
            clues.append("指數小漲，偏震盪回穩")
        else:
            clues.append("指數下跌或壓回")

    main_count = status_counts.get("明面主流", 0)
    stealth_count = status_counts.get("偷偷流入", 0)
    low_count = status_counts.get("低基期轉強", 0)
    pullback_count = status_counts.get("回檔轉強", 0)
    weak_count = status_counts.get("退潮轉弱", 0)

    if main_count >= 3:
        clues.append(f"明面主流 {main_count} 組，市場資金有明顯追價族群")
    elif stealth_count + pullback_count + low_count >= 6:
        clues.append(f"偷偷流入/回檔轉強/低基期合計 {stealth_count + pullback_count + low_count} 組，偏資金回補但未全面主流化")
    elif weak_count >= 10:
        clues.append(f"退潮轉弱 {weak_count} 組，代表指數上漲可能集中在少數權值，不是全面擴散")
    else:
        clues.append("族群廣度普通，需看權值股與法人是否主導")

    if foreign is not None:
        if foreign > 100:
            clues.append(f"外資買超約 {foreign:.1f} 億，偏外資回補/權值拉抬")
        elif foreign < -100:
            clues.append(f"外資賣超約 {abs(foreign):.1f} 億，指數若上漲可能由內資或軋空推動")
        else:
            clues.append("外資買賣超不大，指數來源需看內資與權值結構")

    if trust is not None and trust > 20:
        clues.append(f"投信買超約 {trust:.1f} 億，內資偏多")
    if dealer is not None and abs(dealer) >= 20:
        clues.append(f"自營商買賣超約 {dealer:.1f} 億，留意避險/短線交易影響")

    if external_score is not None:
        if external_score >= 65:
            clues.append("外部環境偏助攻，台股承接力較強")
        elif external_score <= 40:
            clues.append("外部環境仍有壓力，台股上漲需看是否只是短線修復")

    if change_pct is not None and change_pct >= 2 and main_count == 0:
        conclusion = "指數強、族群未全面擴散；較像權值/外資/大型股拉動。"
    elif main_count >= 3:
        conclusion = "指數與族群同步偏強，屬擴散型上漲。"
    elif stealth_count + pullback_count + low_count >= 6:
        conclusion = "市場偏回補型上漲，資金有回流但主流尚未完全定調。"
    elif weak_count >= 10:
        conclusion = "指數上漲但退潮族群仍多，需小心只漲權值、不漲多數股票。"
    else:
        conclusion = "上漲來源混合，需搭配法人與外部環境確認。"

    return {
        "close": close,
        "change_pct": change_pct,
        "status_counts": status_counts,
        "institutional": inst,
        "external_score": external_score,
        "clues": clues,
        "conclusion": conclusion,
    }


def render_after_market_funds_card(snapshot: Dict[str, Any], compact: bool = False) -> None:
    """盤後資金結構。

    v3.2.1：
    - compact=True 時給總裁決內嵌使用
    - 拿掉「說明」欄，避免手機畫面太擠
    """
    inst = snapshot.get("institutional") or {}
    status = (snapshot.get("statuses") or {}).get("盤後資金結構") or {}

    title = "💰 盤後資金結構"
    if not compact:
        st.markdown(f"### {title}")

    if not inst:
        st.info("尚未更新盤後資金結構。請按上方「更新大盤資料」後查看。")
        return

    def fmt_bil(v):
        x = to_float(v)
        if x is None:
            return "—"
        sign = "+" if x > 0 else ""
        return f"{sign}{x:.1f} 億"

    source = compute_market_rise_sources(snapshot)
    counts = source.get("status_counts") or {}
    main_count = counts.get("明面主流", 0)
    stealth_count = counts.get("偷偷流入", 0)
    pullback_count = counts.get("回檔轉強", 0)
    weak_count = counts.get("退潮轉弱", 0)

    if main_count >= 3:
        smart = "強"
    elif stealth_count + pullback_count >= 6:
        smart = "中偏強"
    elif weak_count >= 10:
        smart = "弱 / 偏權值"
    else:
        smart = "中性"

    rows = [
        {"項目": "外資", "買賣超": fmt_bil(inst.get("foreign"))},
        {"項目": "投信", "買賣超": fmt_bil(inst.get("investment_trust"))},
        {"項目": "自營商", "買賣超": fmt_bil(inst.get("dealer"))},
        {"項目": "三大法人合計", "買賣超": fmt_bil(inst.get("total_inst"))},
        {"項目": "其他資金推估", "買賣超": fmt_bil(inst.get("other_estimate"))},
        {"項目": "主力跡象", "買賣超": smart},
    ]

    if compact:
        st.markdown("#### 💰 盤後資金結構")
        st.caption(f"來源：{inst.get('source', 'TWSE')}｜{status.get('note', '')}")
    else:
        st.caption(f"來源：{inst.get('source', 'TWSE')}｜{status.get('note', '')}")

    st.dataframe(pd.DataFrame(rows), use_container_width=True, hide_index=True)


def render_market_rise_sources_card(snapshot: Dict[str, Any]) -> None:
    """總覽頁：今日大盤上漲來源。"""
    src = compute_market_rise_sources(snapshot)
    st.markdown("### 🔍 今日大盤上漲來源")
    st.markdown(f"**結論：{src.get('conclusion', '—')}**")
    clues = src.get("clues") or []
    if clues:
        for c in clues[:8]:
            st.markdown(f"- {c}")
    else:
        st.caption("尚無足夠資料判斷。")

