# =========================================================
def update_market(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    statuses = snapshot.get("statuses") or {}
    df, err = fetch_market_kline()
    if df is None:
        statuses["大盤K線"] = status_item("fail", False, err)
        snapshot["statuses"] = statuses
        add_log(snapshot, "更新大盤資料", f"失敗：{err}")
        save_snapshot(snapshot)
        return snapshot

    # Yahoo 日K盤後常延遲；收盤後用 TWSE MIS 補上最新加權收盤，避免看起來沒更新。
    realtime_quote, realtime_err = fetch_market_realtime_quote()
    df, realtime_merged, realtime_note = merge_market_realtime_quote_for_update(df, realtime_quote)

    sr = detect_volume_k_sr_lines(df)
    levels = compute_key_levels(df, sr)
    ma_deduction = compute_ma_deduction(df)
    k_note = f"成功更新至 {normalize_date_str(df['date'].iloc[-1])}"
    twse_merge_note = getattr(df, "attrs", {}).get("twse_merge_note", "")
    if twse_merge_note:
        k_note += f"｜{twse_merge_note}"
    if realtime_merged:
        k_note += f"｜{realtime_note}"
    elif realtime_err:
        k_note += f"｜即時補值未使用：{realtime_err}"
    else:
        k_note += f"｜即時補值未使用：{realtime_note}"
    statuses["大盤K線"] = status_item("ok", True, k_note)
    statuses["支撐壓力"] = status_item("ok", True, f"偵測 {len(sr)} 條大量K支撐壓力")
    statuses["均線扣抵"] = status_item("ok", True, f"{ma_deduction.get('state', '—')}；{ma_deduction.get('summary', '')}")
    verdict = apply_context_to_verdict(compute_market_verdict(df, levels, statuses), snapshot)

    last = df.iloc[-1]
    snapshot["market"] = {
        "updated_at": now_tw().strftime("%Y-%m-%d %H:%M:%S"),
        "kline": df_to_records(df),
        "sr_lines": sr,
        "levels": levels,
        "ma_deduction": ma_deduction,
        "last": {
            "date": normalize_date_str(last.get("date")),
            "close": to_float(last.get("close")),
            "change_pct": verdict.get("change_pct"),
        },
        "realtime_quote": realtime_quote,
        "realtime_merged": bool(realtime_merged),
        "realtime_note": realtime_note,
        "verdict": verdict,
    }

    # 盤後資金結構：跟大盤資料一起更新，避免總覽頁缺法人買賣超。
    inst_data, inst_status = fetch_twse_institutional_amount()
    if inst_data:
        snapshot["institutional"] = inst_data
    statuses["盤後資金結構"] = inst_status

    snapshot["statuses"] = statuses
    add_log(snapshot, "更新大盤資料", f"{k_note}｜{inst_status.get('note', '')}")
    save_snapshot(snapshot)
    return snapshot


def update_discovery(snapshot: Dict[str, Any], max_per_sector: int = 3) -> Dict[str, Any]:
    discovery, status, pool = discover_online_candidates(max_per_sector=max_per_sector)
    snapshot["discovery"] = discovery
    snapshot["discovered_pool"] = pool
    statuses = snapshot.get("statuses") or {}
    statuses["聯網新增標的"] = status
    snapshot["statuses"] = statuses
    add_log(snapshot, "聯網新增標的", status.get("note", "完成"))
    save_snapshot(snapshot)
    return snapshot


def update_external(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    external, status = fetch_external_risk_snapshot()
    snapshot["external"] = external
    statuses = snapshot.get("statuses") or {}
    statuses["外部風險"] = status
    snapshot["statuses"] = statuses

    market = snapshot.get("market") or {}
    df = records_to_df(market.get("kline"))
    if not df.empty:
        verdict = apply_context_to_verdict(compute_market_verdict(df, market.get("levels") or {}, statuses), snapshot)
        snapshot["market"]["verdict"] = verdict

    add_log(snapshot, "更新外部風險", status.get("note", "完成"))
    save_snapshot(snapshot)
    return snapshot


def update_news(snapshot: Dict[str, Any]) -> Dict[str, Any]:
    news, status = fetch_news_snapshot()
    snapshot["news"] = news
    statuses = snapshot.get("statuses") or {}
    statuses["新聞快照"] = status
    snapshot["statuses"] = statuses

    market = snapshot.get("market") or {}
    df = records_to_df(market.get("kline"))
    if not df.empty:
        verdict = apply_context_to_verdict(compute_market_verdict(df, market.get("levels") or {}, statuses), snapshot)
        snapshot["market"]["verdict"] = verdict

    add_log(snapshot, "更新新聞快照", status.get("note", "完成"))
    save_snapshot(snapshot)
    return snapshot


def update_flow(snapshot: Dict[str, Any], selected_sectors: List[str], max_stocks_each: int) -> Dict[str, Any]:
    flow, status = analyze_sector_flow(selected_sectors, max_stocks_each=max_stocks_each, extra_pool=snapshot.get("discovered_pool") or {})
    snapshot["flow"] = flow

    # 共用資金流向：大盤更新後，同步寫入個股 App 使用的 nick_dynamic_flow.json。
    sync_result = sync_market_flow_to_stock_app(snapshot)

    # 資金流向更新後，自動產生個股雷達要掃描的族群。
    snapshot["radar_auto_sectors"] = auto_radar_sectors_from_flow(snapshot, AUTO_RADAR_DEFAULT_STATUSES)
    statuses = snapshot.get("statuses") or {}
    statuses["資金流向"] = status
    snapshot["statuses"] = statuses

    # 更新總裁決版本：資金流向成功後，重新計算一次 verdict
    market = snapshot.get("market") or {}
    df = records_to_df(market.get("kline"))
    if not df.empty:
        verdict = apply_context_to_verdict(compute_market_verdict(df, market.get("levels") or {}, statuses), snapshot)
        snapshot["market"]["verdict"] = verdict

    add_log(snapshot, "更新資金流向", f"{status.get('note', '完成')}｜{sync_result.get('note', '')}")
    save_snapshot(snapshot)
    return snapshot


def update_radar(snapshot: Dict[str, Any], selected_sectors: List[str], max_stocks_each: int, radar_mode: str = "inflow") -> Dict[str, Any]:
    # 個股雷達股票池 = 最新資金流向代表股 + 聯網新增候選 + 內建族群。
    # 依照不同按鈕，只把對應資金狀態放進動態池，避免佈局/退潮混在一起。
    mode_statuses = radar_statuses_for_mode(radar_mode)
    dynamic_pool = build_flow_sector_pool(snapshot, statuses=mode_statuses)
    extra_pool = merge_sector_pools(dynamic_pool, snapshot.get("discovered_pool") or {})
    lookup = flow_status_lookup(snapshot)
    radar, status = scan_sector_stock_radar(
        selected_sectors,
        max_stocks_each=max_stocks_each,
        extra_pool=extra_pool,
        radar_mode=radar_mode,
        sector_status_lookup=lookup,
    )
    radar["sector_source"] = "資金流向同步 + 聯網候選 + 內建族群"
    radar["scan_statuses"] = mode_statuses
    # 保留舊欄位相容，同時依模式分開存，讓「資金流入 / 資金退潮」兩頁不互相覆蓋。
    snapshot["radar"] = radar
    radar_by_mode = snapshot.get("radar_by_mode") or {}
    radar_by_mode[radar_mode] = radar
    snapshot["radar_by_mode"] = radar_by_mode
    statuses = snapshot.get("statuses") or {}
    status_key = "個股雷達｜" + RADAR_MODE_LABELS.get(radar_mode, "資金流入佈局")
    statuses[status_key] = status
    snapshot["statuses"] = statuses
    add_log(snapshot, status_key, status.get("note", "完成"))
    save_snapshot(snapshot)
    return snapshot


