def get_radar_data_for_mode(snapshot: Dict[str, Any], mode: str) -> Dict[str, Any]:
    """讀取指定模式的個股雷達資料；舊版快照只存在 snapshot['radar'] 時也能相容。"""
    radar_by_mode = snapshot.get("radar_by_mode") or {}
    radar = radar_by_mode.get(mode)
    if isinstance(radar, dict) and radar.get("rows"):
        return radar

    legacy = snapshot.get("radar") or {}
    if legacy.get("mode") == mode:
        return legacy
    return {"mode": mode, "mode_label": RADAR_MODE_LABELS.get(mode, mode), "rows": []}


def prepare_radar_display_df(radar: Dict[str, Any]) -> pd.DataFrame:
    rows = radar.get("rows") or []
    df = pd.DataFrame(rows)
    if df.empty:
        return df

    show = df.copy()
    for c in ["法人5日", "法人20日"]:
        if c in show.columns:
            show[c] = show[c].apply(fmt_shares)
    for c in ["月營收YoY", "5日漲跌", "20日漲跌", "量比"]:
        if c in show.columns:
            show[c] = show[c].apply(fmp if c != "量比" else lambda x: "—" if to_float(x) is None else f"{to_float(x):.2f}x")
    return show



def parse_radar_stock_label(value: Any) -> Tuple[Optional[str], str]:
    """從雷達表格的「股票」欄解析出代號與名稱，例如：鴻海 2317。"""
    s = str(value or "").strip()
    if not s:
        return None, ""
    m = re.search(r"(\d{4}[A-Za-z]?)", s)
    if not m:
        return None, s
    code = m.group(1).strip()
    name = s[: m.start()].strip(" ｜|　\t")
    if not name:
        name = s[m.end():].strip(" ｜|　\t") or code
    return code, name


def build_radar_stock_options(df: pd.DataFrame) -> List[Dict[str, str]]:
    """保留原表格格式，另外產生快速分析下拉選單資料。"""
    if df is None or df.empty or "股票" not in df.columns:
        return []
    options: List[Dict[str, str]] = []
    seen = set()
    for raw in df["股票"].dropna().tolist():
        code, name = parse_radar_stock_label(raw)
        if not code or code in seen:
            continue
        seen.add(code)
        label = f"{name} {code}" if name and name != code else code
        options.append({"label": label, "code": code, "name": name or code})
    return options


def render_radar_quick_analyze_selector(df: pd.DataFrame, key_prefix: str) -> None:
    """雷達表格下方的一鍵個股分析，不改動原本 st.dataframe 表格。"""
    options = build_radar_stock_options(df)
    if not options:
        return

    st.markdown("##### 🔎 快速分析本區標的")
    c1, c2 = st.columns([2.2, 1])
    with c1:
        selected_label = st.selectbox(
            "選擇要帶入個股法醫分析器的標的",
            [o["label"] for o in options],
            key=f"radar_quick_select_{key_prefix}",
            label_visibility="collapsed",
        )
    selected = next((o for o in options if o["label"] == selected_label), options[0])
    with c2:
        if st.button("開始分析", key=f"radar_quick_btn_{key_prefix}", use_container_width=True):
            st.session_state["stock_code_input"] = selected["code"]
            st.session_state["stock_name_input"] = selected["name"]
            st.session_state["auto_run_hot_stock"] = True
            st.session_state["main_nav_page"] = "個股法醫分析器"
            st.session_state["radar_quick_analyze_note"] = f"已從雷達帶入：{selected['name']} {selected['code']}"
            # 主選單已改為 query param 導覽；從雷達跳個股時同步更新 URL，避免被舊頁籤覆蓋。
            try:
                st.query_params["nav"] = "個股法醫分析器"
            except Exception:
                try:
                    st.experimental_set_query_params(nav="個股法醫分析器")
                except Exception:
                    pass
            try:
                st.rerun()
            except Exception:
                st.experimental_rerun()

def render_radar_group_expanders(show: pd.DataFrame, sections: List[Tuple[str, List[str]]], cols: List[str]) -> None:
    for title, source_statuses in sections:
        if show.empty or "狀態" not in show.columns:
            part = pd.DataFrame()
        else:
            part = show[show["狀態"].isin(source_statuses)].copy()

        with st.expander(f"{title}（{len(part)}）", expanded=False):
            if part.empty:
                st.caption("目前沒有符合標的。")
            else:
                display_cols = [c for c in cols if c in part.columns]
                st.dataframe(part[display_cols], use_container_width=True, hide_index=True)
                render_radar_quick_analyze_selector(part, f"group_{re.sub(r'[^0-9A-Za-z_]+', '_', title)}")


def render_radar_by_sector_expander(show: pd.DataFrame, cols: List[str], title: str, allowed_statuses: Optional[List[str]] = None) -> None:
    if show.empty or "族群" not in show.columns:
        with st.expander(f"{title}（0）", expanded=False):
            st.caption("目前沒有資料。")
        return

    work = show.copy()
    if allowed_statuses and "狀態" in work.columns:
        work = work[work["狀態"].isin(allowed_statuses)].copy()

    sectors = sorted([x for x in work["族群"].dropna().unique() if str(x).strip()])
    with st.expander(f"{title}（{len(sectors)} 組）", expanded=False):
        if work.empty:
            st.caption("目前沒有符合標的。")
            return
        for sector in sectors:
            st.markdown(f"##### {sector}")
            sdf = work[work["族群"] == sector]
            display_cols = [c for c in cols if c in sdf.columns]
            st.dataframe(sdf[display_cols], use_container_width=True, hide_index=True)
            render_radar_quick_analyze_selector(sdf, f"sector_{re.sub(r'[^0-9A-Za-z_]+', '_', str(sector))}")


def render_radar_page(snapshot: Dict[str, Any], mode: str) -> None:
    radar = get_radar_data_for_mode(snapshot, mode)
    rows = radar.get("rows") or []
    mode_label = RADAR_MODE_LABELS.get(mode, "資金流入佈局" if mode == "inflow" else "資金退潮風險")
    title_emoji = "🧬" if mode == "inflow" else "⚠️"

    st.markdown(f"### {title_emoji} 族群個股雷達｜{mode_label}")
    st.caption(
        f"更新：{radar.get('updated_at', '—')}｜族群來源：{radar.get('sector_source', '—')}｜"
        f"掃描狀態：{', '.join(radar.get('scan_statuses', [])) or '—'}"
    )

    if not rows:
        btn_text = "掃資金流入佈局" if mode == "inflow" else "掃資金退潮"
        st.info(f"尚未掃描這一頁。請按上方『{btn_text}』。")
        return

    show = prepare_radar_display_df(radar)
    if show.empty:
        st.info("目前沒有個股雷達資料。")
        return

    if mode == "inflow":
        st.caption("此頁只顯示資金流入佈局相關分類；「佈局觀察中」已隱藏。基本面轉強條件改為「法人短線剛卡位」，避免把法人調節或出貨誤判成法人未跟上。")
        cols = ["族群", "族群資金狀態", "股票", "狀態", "法人5日", "法人20日", "月營收YoY", "5日漲跌", "20日漲跌", "量比", "位置", "操作", "操作提醒"]
        sections = [
            ("優先佈局", ["優先佈局觀察"]),
            ("偷偷回補", ["偷偷回補觀察"]),
            ("低基期轉強", ["低基期轉強觀察"]),
            ("回檔轉強", ["回檔轉強觀察"]),
            ("基本面轉強，法人剛卡位", ["基本面轉強，法人剛卡位"]),
            ("位置過熱不追", ["位置過熱，不追", "題材先跑，基本面待驗證"]),
        ]
        render_radar_group_expanders(show, sections, cols)
        allowed = []
        for _, values in sections:
            allowed.extend(values)
        render_radar_by_sector_expander(show, cols, "依族群展開｜資金流入族群", allowed_statuses=allowed)
    else:
        st.caption("此頁專看資金退潮、法人賣壓、跌破風險；弱勢但沒有明確退潮的雜訊不放主畫面。")
        cols = ["族群", "族群資金狀態", "股票", "狀態", "風險等級", "法人5日", "法人20日", "月營收YoY", "5日漲跌", "20日漲跌", "位置", "操作", "操作提醒"]
        sections = [
            ("明確退潮，先避開", ["明確退潮，先避開"]),
            ("高檔鈍化，不追高", ["高檔鈍化，不追高"]),
            ("基本面沒壞，但資金短退", ["基本面沒壞，但資金短退"]),
            ("疑似洗盤，觀察支撐", ["疑似洗盤，觀察支撐"]),
            ("反彈逃命股", ["反彈逃命股"]),
        ]
        render_radar_group_expanders(show, sections, cols)
        allowed = []
        for _, values in sections:
            allowed.extend(values)
        render_radar_by_sector_expander(show, cols, "依族群展開｜資金退潮族群", allowed_statuses=allowed)


